FROM node:14

RUN mkdir /app
WORKDIR /app

# install deps before deploying the code
ADD package.json /app
RUN yarn

# add the code
ADD . /app

ENV PORT=8080
EXPOSE $PORT

CMD [ "usr/bin/env", "node", "/app" ]
import * as redis from 'redis';
import * as http from 'http';

const client = redis.createClient({
  password: process.env.REDIS_PASSWORD,
  host: process.env.REDIS_MASTER,
});

const port = process.env.PORT ?? 8080;

const server = http.createServer((req, res) => {

  if (req.method === 'GET') {
    return client.get('counter', (err, data) => {
      if (err) {
        return res.end(err.message);
      }

      if (!data) {
        return res.end('no data\n');
      }

      return res.end(`counter=${data}\n`);
    });
  }

  if (req.method === 'POST') {
    return client.incr('counter', (err, data) => {
      if (err) {
        return res.end(err.message);
      }

      return res.end(`counter=${data}\n`);
    });
  }

  res.statusCode = 404;
  return res.end('not found\n');
});

console.error(`listening on port ${port}`);
server.listen(port);
{
  "dependencies": {
    "redis": "^3.0.2"
  }
}
FROM node:14

ADD . /app
WORKDIR /app
CMD [ "/app/index.js" ]
#!/usr/bin/env node
const http = require('http');
const os = require('os');

const server = http.createServer((req, res) => {
  res.write('hello, world\n');
  res.write(`url=${req.url}\n`);
  res.write(`host=${os.hostname()}`);

  res.end();
});

process.on('SIGINT', () => process.exit(1));

const port = process.env.PORT ?? 8080;
server.listen(port);
console.error(`listening on port ${port}`);
import { App, Chart, ChartOptions } from 'cdk8s';
import { EnvValue } from 'cdk8s-plus';
import { Construct } from 'constructs';
import { Router } from '../router';
import { Redis } from './redis';

class MyChart extends Chart {
  constructor(scope: Construct, id: string, opts: ChartOptions = {}) {
    super(scope, id, opts);

    const redis = new Redis(this, 'tasks');
    const router = new Router(this, 'router');

    router.addBackend('/hello', `${__dirname}/hello`);

    router.addBackend('/counter', `${__dirname}/counter`, {
      replicas: 3,
      env: {
        REDIS_PASSWORD: EnvValue.fromSecretValue(redis.password),
        REDIS_MASTER: EnvValue.fromValue(redis.masterHost),
        REDIS_SLAVE: EnvValue.fromValue(redis.slaveHost),
      },
    });

    router.addBackend('/redis', `${__dirname}/redis-ui`, {
      registry: 'localhost:5000',
      readinessUrl: '/redis',
      port: 8081,
      env: {
        REDIS_HOST: EnvValue.fromValue(redis.masterHost),
        REDIS_PASSWORD: EnvValue.fromSecretValue(redis.password),
        URL_PREFIX: EnvValue.fromValue('/redis'),
      },
    });
  }
}

const app = new App();
new MyChart(app, 'test', {
  labels: { prune: 'kubecon-demo' },
});
app.synth();
